//! Guitarix (legado/plugins/Guitarix/GuitarixControlDialog.cpp, GuitarixLayout.cpp, GuitarixSelectors.cpp): every unit
//! is its own plugin (`gx-<unit>`), and its panel is the rack unit the legacy dialog builds: the title on the brushed
//! panel between the two handles and the screws, and the unit's controls at the places the glade layout gives them.
//!
//! The 97 units are one table, [`guitarix_units`] (generated by `tools/gen_guitarix_panels.py` from the layout trees
//! in docs/plugins-visual.md and from what each unit registers), and this file turns each into a [`PanelSpec`]: the
//! knobs in Guitarix's four sizes with their LED rings, the switches, the selectors (the amp head's tubes, the
//! tonestacks, the cabinets, the wahs...), the sliders, the value displays, the LED meters on the plugin's live
//! frame, and a notebook's tabs as the panel's views. The amp head shows its big gain knob only without an amp
//! (`showAmpControls`: the tube selector on "noamp") and its pre-gain, drive and clean/dist knobs only with one.
//!
//! Putting the units in a chain, reordering them and switching them on and off is the host's insert list, as for any
//! effect (the legacy rack's own on/off button does not exist in the legacy plugin either). The meters of the overall
//! rack output (`maxlevel`, `hardlim`) are the unit's outputs in the live frame.

use std::collections::BTreeMap;
use std::sync::LazyLock;

use super::guitarix_units::UNITS;
use crate::gxwidgets::{self as gx, GxKnob};
use crate::spec::{Bind, ComboItem, Control, PanelSpec, StaticText, SurfaceSpec, Text, combo, knob, surface, toggle};
use crate::widgets::KnobStyle;

/// What a table row is
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum K {
    Label,
    Small,
    SmallR,
    Mid,
    Big,
    Switch,
    MiniToggle,
    SwitchMid,
    FrButton,
    Selector,
    VSlider,
    HSlider,
    Meter,
    Value,
    Tab,
    Dark,
}

/// One control of a unit at its place (panel pixels)
#[derive(Clone, Copy, Debug)]
pub struct Item {
    pub k: K,
    /// The state key of the parameter or field (empty for a label, a tab or a dark box)
    pub key: &'static str,
    /// The parameter's name, or the label's text
    pub name: &'static str,
    pub x: f32,
    pub y: f32,
    pub w: f32,
    pub h: f32,
    /// The notebook page it is on (255: always)
    pub view: u8,
    /// The amp head's condition: 1 only without an amp, 2 only with one
    pub cond: u8,
    pub step: f64,
    /// A knob's or slider's logarithmic flag, a value display's digits, a label's pixel size
    pub a: u32,
    /// A label's color, a meter's tag
    pub b: u32,
    pub opts: &'static [(&'static str, &'static str)],
}

#[allow(clippy::too_many_arguments)]
pub const fn i(
    k: K,
    key: &'static str,
    name: &'static str,
    x: f32,
    y: f32,
    w: f32,
    h: f32,
    view: u8,
    cond: u8,
    step: f64,
    a: u32,
    b: u32,
    opts: &'static [(&'static str, &'static str)],
) -> Item {
    Item { k, key, name, x, y, w, h, view, cond, step, a, b, opts }
}

/// A unit: Guitarix's id, its title, its window's size and its controls
#[derive(Clone, Copy, Debug)]
pub struct Unit {
    pub unit: &'static str,
    pub title: &'static str,
    pub w: f32,
    pub h: f32,
    pub items: &'static [Item],
}

/// The plugin id of a unit (`lm-plugins-guitarix`: `gx-` and the unit's id in lower case, every run of other
/// characters a `-`)
pub fn plugin_id(unit: &str) -> String {
    let mut id = String::from("gx-");
    let mut dash = false;
    for c in unit.chars() {
        if c.is_ascii_alphanumeric() {
            if dash && !id.ends_with('-') {
                id.push('-');
            }
            dash = false;
            id.push(c.to_ascii_lowercase());
        } else {
            dash = true;
        }
    }
    id
}

/// The amp head's tube selector, and its last value (no amp)
const TUBE: &str = "tube_select";
const NO_AMP: &str = "noamp";

/// A surface that only draws (the skin, a dark box, a meter): no parameter, no handles, not hit by the mouse
fn decoration(w: f32, h: f32, draw: crate::spec::SurfDrawFn, live: bool, tag: u32) -> SurfaceSpec {
    SurfaceSpec {
        w,
        h,
        primary: "",
        reads: &[],
        field_reads: &[],
        draw,
        texts: None,
        handles: None,
        drag: None,
        grab: 0.0,
        set_on_press: false,
        live,
        wheel: false,
        wheel_edit: None,
        peaks: None,
        tag,
        markers: None,
    }
}

fn knob_kind(k: K) -> GxKnob {
    match k {
        K::Small => GxKnob::Small,
        K::Mid => GxKnob::Mid,
        K::Big => GxKnob::Big,
        _ => GxKnob::SmallR,
    }
}

fn intern(s: &str) -> &'static str {
    lm_port::intern(s)
}

fn restrict(c: Control, it: &Item) -> Control {
    let c = if it.view == 255 { c } else { c.in_view_n(it.view) };
    match it.cond {
        1 => c.only_while(TUBE, NO_AMP),
        2 => c.hidden_while(TUBE, NO_AMP),
        _ => c,
    }
}

fn build(u: &'static Unit) -> PanelSpec {
    let id = intern(&plugin_id(u.unit));
    let mut controls: Vec<Control> =
        vec![surface(decoration(u.w, u.h, gx::skin_surface, false, 0), "skin", 0.0, 0.0, "Unit")];
    let mut labels =
        vec![StaticText { x: 36.0, y: 8.0, px: 13.0, text: Text::new(u.title), color: 0x222222, view: None }];
    for it in u.items {
        match it.k {
            K::Label => labels.push(StaticText {
                x: it.x,
                y: it.y,
                px: it.a as f32,
                text: Text::new(it.name),
                color: it.b,
                view: (it.view != 255).then_some(it.view),
            }),
            K::Dark => {
                controls.push(surface(decoration(it.w, it.h, gx::dark_surface, false, 0), "dark", it.x, it.y, "Panel"))
            }
            K::Tab => {
                controls.push(toggle(
                    Bind::View(it.view),
                    intern(&format!("tab{}", it.view)),
                    it.x,
                    it.y,
                    it.w,
                    it.h,
                    gx::draw_tab,
                    it.name,
                ));
                labels.push(StaticText {
                    x: it.x + 8.0,
                    y: it.y + 4.0,
                    px: 9.0,
                    text: Text::new(it.name),
                    color: 0xd37a00,
                    view: None,
                });
            }
            K::Small | K::SmallR | K::Mid | K::Big => {
                let hint = intern(&format!("{}:", it.name));
                let mut c = knob(it.key, it.x, it.y, KnobStyle::Gx(knob_kind(it.k)), it.step, it.name, hint, "");
                if it.a != 0 {
                    c = c.log();
                }
                controls.push(restrict(c, it));
            }
            K::Switch | K::MiniToggle | K::SwitchMid | K::FrButton => {
                let (w, h, draw): (f32, f32, fn(&mut crate::raster::Canvas, bool)) = match it.k {
                    K::MiniToggle => (gx::MINITOGGLE_SIZE, gx::MINITOGGLE_SIZE, gx::draw_minitoggle),
                    K::SwitchMid => (gx::MINITOGGLE_SIZE, gx::MINITOGGLE_SIZE, gx::draw_switch_mid),
                    K::FrButton => (gx::FRBUTTON_W, gx::FRBUTTON_H, gx::draw_frbutton),
                    _ => (gx::SWITCH_SIZE, gx::SWITCH_SIZE, gx::draw_switch),
                };
                controls.push(restrict(
                    toggle(Bind::Switch { param: it.key }, it.key, it.x, it.y, w, h, draw, it.name),
                    it,
                ));
            }
            K::Selector => {
                let items = it
                    .opts
                    .iter()
                    .map(|(key, text)| ComboItem { key, text: Text::new(text), icon: None })
                    .collect::<Vec<_>>();
                controls.push(restrict(combo(it.key, it.x, it.y, it.w, it.name, items).gx(), it));
            }
            K::VSlider | K::HSlider => {
                let horizontal = it.k == K::HSlider;
                let tag = u32::from(it.a != 0) | (u32::from(horizontal) << 1);
                let reads: &'static [&'static str] = Box::leak(vec![it.key].into_boxed_slice());
                let spec = SurfaceSpec {
                    w: it.w,
                    h: it.h,
                    primary: it.key,
                    reads,
                    field_reads: &[],
                    draw: gx::draw_slider,
                    texts: None,
                    handles: Some(gx::slider_handles),
                    drag: Some(gx::slider_drag),
                    grab: f32::INFINITY,
                    set_on_press: true,
                    live: false,
                    wheel: true,
                    wheel_edit: None,
                    peaks: None,
                    tag,
                    markers: None,
                };
                controls.push(restrict(surface(spec, it.key, it.x, it.y, it.name), it));
            }
            K::Meter => {
                let spec = decoration(it.w, it.h, gx::draw_meter, true, it.b);
                controls.push(restrict(surface(spec, "meter", it.x, it.y, it.name), it));
            }
            K::Value => {
                let reads: &'static [&'static str] = Box::leak(vec![it.key].into_boxed_slice());
                let spec = SurfaceSpec {
                    w: it.w,
                    h: it.h,
                    primary: it.key,
                    reads,
                    field_reads: &[],
                    draw: gx::draw_value,
                    texts: Some(gx::value_texts),
                    handles: None,
                    drag: None,
                    grab: 0.0,
                    set_on_press: false,
                    live: false,
                    wheel: false,
                    wheel_edit: None,
                    peaks: None,
                    markers: None,
                    tag: it.a,
                };
                controls.push(restrict(surface(spec, it.key, it.x, it.y, it.name), it));
            }
        }
    }
    PanelSpec {
        plugin: id,
        size: (u.w, u.h),
        background: None,
        view_backgrounds: &[],
        fill: 0x1d1d1d,
        controls,
        labels,
        file_drop: None,
    }
}

static PANELS: LazyLock<BTreeMap<&'static str, PanelSpec>> = LazyLock::new(|| {
    UNITS
        .iter()
        .map(|u| {
            let p = build(u);
            (p.plugin, p)
        })
        .collect()
});

/// The panel of a Guitarix unit by its plugin id (`gx-ts9sim`)
pub fn spec(plugin: &str) -> Option<&'static PanelSpec> {
    if !plugin.starts_with("gx-") {
        return None;
    }
    PANELS.get(plugin)
}

/// Every Guitarix unit's plugin id, in the legacy browser's order
pub fn ids() -> Vec<&'static str> {
    UNITS.iter().filter_map(|u| PANELS.get(plugin_id(u.unit).as_str()).map(|p| p.plugin)).collect()
}
